const counts={props:27,edges:8};const comparisons=[];
for(let k=0;k<27;k++){
 const can=JSON.parse(await tools.read_task_input({id:"nl0.json",pointer:"/propositions/"+k}));
 const over=JSON.parse(await tools.read_task_input({id:"global-overview.json",pointer:k<2?"/graph_hypotheses/"+k:"/other_propositions/"+(k-2)}));
 if(can.has_more||over.has_more||can.view!=="value"||over.view!=="value")throw Error("Incomplete read "+k);
 store("prop"+k,can.value);
 comparisons.push({id:can.value.id,equal:JSON.stringify(can.value)===JSON.stringify(over.value.record)});
}
text({canonical_proposition_comparisons:comparisons});
for(let k=0;k<8;k++){
 const inp=JSON.parse(await tools.read_task_input({id:"nl0.json",pointer:"/inferences/"+k+"/inputs"}));
 const out=JSON.parse(await tools.read_task_input({id:"nl0.json",pointer:"/inferences/"+k+"/output"}));
 const over=JSON.parse(await tools.read_task_input({id:"global-overview.json",pointer:"/inference_edges/"+k}));
 store("edge"+k,{inputs:inp.value,output:out.value});
 text({id:over.value.id,input_match:JSON.stringify(inp.value)===JSON.stringify(over.value.inputs),output_match:out.value===over.value.output});
}

